// src/pages/notifications/NotificationStatsPage.jsx
import React, { useEffect, useMemo, useState } from 'react';
import NotificationStatusChart from '../../components/notifications/NotificationStatusChart';
import { fetchAlertStats } from '../../api/NotificationsApi';

function toYmd(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function NotificationStatsPage() {
  const today = useMemo(() => new Date(), []);
  const [range, setRange] = useState('daily'); // daily|weekly
  const [from, setFrom] = useState(toYmd(new Date(today.getFullYear(), today.getMonth(), today.getDate() - 6)));
  const [to, setTo] = useState(toYmd(today));

  const [counter, setCounter] = useState({ total: 0, DANGER: 0, WARNING: 0, SAFE: 0, UNKNOWN: 0 });
  const [series, setSeries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetchAlertStats({ range, from, to });
      setCounter(res.counter);
      setSeries(res.series);
    } catch (e) {
      setError(e);
      setCounter({ total: 0, DANGER: 0, WARNING: 0, SAFE: 0, UNKNOWN: 0 });
      setSeries([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [range, from, to]);

  return (
    <div className="page-container">
      <h1>알림 통계</h1>

      <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', marginBottom: 12 }}>
        <label>
          집계 단위:&nbsp;
          <select value={range} onChange={(e) => setRange(e.target.value)}>
            <option value="daily">일별</option>
            <option value="weekly">주별(월요일 시작)</option>
          </select>
        </label>

        <label>
          From:&nbsp;
          <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
        </label>

        <label>
          To:&nbsp;
          <input type="date" value={to} onChange={(e) => setTo(e.target.value)} />
        </label>

        <button className="btn" onClick={load}>새로고침</button>
      </div>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>통계 로드 오류: {error.message}</p>}

      {!loading && !error && (
        <>
          <NotificationStatusChart stats={counter} />

          <div style={{ marginTop: 14 }}>
            <div style={{ fontWeight: 700, marginBottom: 6 }}>
              {range === 'daily' ? '일별' : '주별'} 추이
            </div>

            {series.length === 0 ? (
              <p style={{ color: '#9ca3af' }}>표시할 데이터가 없습니다.</p>
            ) : (
              <table className="log-table" style={{ width: '100%' }}>
                <thead>
                  <tr>
                    <th style={{ width: 140 }}>{range === 'daily' ? '날짜' : '주 시작일'}</th>
                    <th>DANGER</th>
                    <th>WARNING</th>
                    <th>SAFE</th>
                  </tr>
                </thead>
                <tbody>
                  {series.map((r) => (
                    <tr key={r.date}>
                      <td>{r.date}</td>
                      <td>{r.danger}</td>
                      <td>{r.warning}</td>
                      <td>{r.safe}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
}

export default NotificationStatsPage;
